# The die is stable after release at the wooden base, and the red block remains on the left.
# Approach red with the left arm while returning the right arm clear of the stack.
def move_both(target_left, target_right, count=20):
    targets = {'left': np.array(target_left), 'right': np.array(target_right)}
    for i in range(count):
        s = get_observation()['state']
        action = {'left_ee_joint_state': [1.0], 'right_ee_joint_state': [1.0]}
        done = True
        for arm in ['left', 'right']:
            cur = np.array(s[arm + '_ee_pose'])
            goal = targets[arm]
            delta = goal[:3] - cur[:3]
            dist = np.linalg.norm(delta)
            gq = goal[3:]
            if np.sum(gq * cur[3:]) < 0:
                gq = -gq
            if dist > 0.003 or np.linalg.norm(gq - cur[3:]) > 0.015:
                done = False
            cur[:3] += delta * min(1.0, 0.023 / max(dist, 0.00001))
            cur[3:] = cur[3:] * 0.6 + gq * 0.4
            cur[3:] /= np.linalg.norm(cur[3:])
            action[arm + '_ee_pose'] = cur
        if done:
            break
        obs, reward, terminated, truncated, info = step(action)
        if terminated or truncated:
            break
    print('dual approach', i + 1, get_observation()['state'])
